/** Banner for every generated file. No timestamp, so builds are reproducible. */
export function generatedHeader(open: string, close: string): string {
  return [
    open,
    ' * Generated by @mission-ui/tokens from the DTCG files in packages/tokens/tokens. Do not edit.',
    ' * Change the token source and run `pnpm --filter tokens build`.',
    close,
  ].join('\n');
}
